// rc_logic.c - generated by split_c.py from RayCaster.c
#include "rc_priv.h"



bool rc_IsBossLevel(uint16_t lv)
{
    return ((lv + 1u) % RC_BOSS_EVERY) == 0;
}


// Level-up: how much XP the next level needs.
uint16_t rc_XpNeed(void)
{
    return (uint16_t)(24u + 12u * rc_xpLv);
}


static void GainXp(uint16_t amt)
{
    uint16_t need;

    rc_xp += amt;
    for(;;)
    {
        need = rc_XpNeed();
        if(rc_xp < need) break;
        rc_xp -= need;
        rc_xpLv++;
        rc_lvPending++;
    }
    rc_hud |= HUD_XP | HUD_LEVEL;
}


//-----------------------------------------------------------------------------
// Equipment slots
//-----------------------------------------------------------------------------
static bool SlotOwned(uint16_t slot)
{
    if(slot < NUM_STAFF) return (rc_staffOwned & (1u << slot)) != 0;
    return (rc_itemOwned & (1u << (slot - NUM_STAFF))) != 0;
}


const char *rc_SlotName(uint16_t slot)
{
    return (slot < NUM_STAFF) ? rc_kStaff[slot].name : rc_kItem[slot - NUM_STAFF].name;
}


uint32_t rc_SlotColor(uint16_t slot)
{
    return (slot < NUM_STAFF) ? rc_kStaff[slot].color : rc_kItem[slot - NUM_STAFF].color;
}


uint16_t rc_SlotMana(uint16_t slot)
{
    return (slot < NUM_STAFF) ? rc_kStaffMana[slot] : rc_kItemMana[slot - NUM_STAFF];
}


static void DropMana(int16_t x, int16_t y);


static uint16_t StaffCooldown(uint16_t st)
{
    int16_t cd = (int16_t)((rc_kStaff[st].cooldown * (100 - 9 * rc_lvRate)) / 100);

    if(rc_haste) cd >>= 1;
    return (cd < 4) ? 4 : (uint16_t)cd;
}


void rc_CycleEquip(void)
{
    uint16_t i, slot = rc_equip;

    for(i = 1; i < NUM_SLOT; i++)
    {
        slot = (slot + 1u) % NUM_SLOT;
        if(SlotOwned(slot)) break;
    }

    if(slot != rc_equip && SlotOwned(slot))
    {
        rc_equip = slot;
        rc_hud  |= HUD_STAFF;
        rc_viewDirty = 2;                // redraw the new item in the hand
        rc_Sfx(&sfx_menu_move);
    }
}


//-----------------------------------------------------------------------------
// Player damage / enemy damage
//-----------------------------------------------------------------------------
void rc_HurtPlayer(void)
{
    if(rc_invuln || rc_hp == 0 || rc_aegis) return;

    rc_hp--;
    rc_invuln = (rc_traits & (1u << TR_THICK)) ? RC_THICK_FRAMES : RC_INVULN_FRAMES;
    rc_hud   |= HUD_HEARTS;
    rc_viewDirty = 2;

    if(rc_hp == 0) rc_EnterOver();
    else          rc_Sfx(&sfx_hit);
}


static void KillEnemy(Enemy *e)
{
    const EnemyDef *d = &rc_kEnemy[e->type];
    uint16_t i, g, xp;
    bool     summoned = (e->type == ET_SKELETON && e->aux == 1);

    e->alive = 0;
    if(rc_alive) rc_alive--;

    if(summoned)                                // the Lich's skeletons: tiny reward
    {
        g  = 2;
        xp = 1;
    }
    else
    {
        g  = (uint16_t)(((uint32_t)d->gold * (100u + 20u * rc_lvGold)) / 100u);
        xp = (uint16_t)(d->xp + rc_level / 4u);
    }

    rc_gold += g;
    rc_kills++;
    rc_hud |= HUD_GOLD | HUD_LEFT;
    GainXp(xp);

    if((rc_traits & (1u << TR_VAMP)) && (rc_kills % 10u) == 0 && rc_hp < rc_maxHp)
    {
        rc_hp++;
        rc_hud |= HUD_HEARTS;
    }

    rc_Sfx(&sfx_explosion);

    if(!summoned && (e->type == ET_LICH || e->type == ET_DRAGON || (Rand16() % 100u) < MANA_DROP_PCT))
        DropMana(e->x, e->y);

    if(e->type == ET_LICH || e->type == ET_DRAGON)
    {
        rc_bossAlive = 0;
        for(i = 0; i < RC_MAX_ENEMIES; i++)         // minions die with their master
            rc_en[i].alive = 0;
        rc_alive = 0;
    }
}


// quiet = damage-over-time / splash tick: no knockback, no frost, no blip.
void rc_DamageEnemyEx(Enemy *e, uint16_t dmg, int16_t c, int16_t s, bool quiet)
{
    e->hp   -= (int16_t)dmg;
    e->flash = 3;
    rc_hud   |= HUD_LEFT;

    if(e->hp <= 0)
    {
        KillEnemy(e);
        return;
    }

    if(quiet) return;

    if((rc_traits & (1u << TR_KNOCK)) && e->type != ET_LICH && e->type != ET_DRAGON)
    {
        int16_t nx = e->x + (int16_t)(((int32_t)c * 260L) >> 14);
        int16_t ny = e->y + (int16_t)(((int32_t)s * 260L) >> 14);

        if(!Blocked(nx, e->y, 220)) e->x = nx;
        if(!Blocked(e->x, ny, 220)) e->y = ny;
    }

    if(rc_traits & (1u << TR_FROST)) e->slow = 90;

    rc_SfxSoft(&sfx_blip);
}


static void DamageEnemy(Enemy *e, uint16_t dmg, int16_t c, int16_t s)
{
    rc_DamageEnemyEx(e, dmg, c, s, false);
}


// Damage scaled by the Damage stat: base * (4 + level) / 4.
static uint16_t ScaledDmg(uint16_t base)
{
    uint16_t d = (uint16_t)((base * (4u + rc_lvDmg) + 2u) >> 2);
    return (d < 1u) ? 1u : d;
}


//-----------------------------------------------------------------------------
// Objects (flasks in flight, clouds, sparks, enemy laser bolts)
//-----------------------------------------------------------------------------
static Obj *NewObj(uint16_t kind)
{
    uint16_t i, pick = 0xFFFFu, oldest = 0;
    Obj     *o;

    for(i = 0; i < RC_MAX_OBJ; i++)
        if(!rc_obj[i].alive) { pick = i; break; }

    if(pick == 0xFFFFu)                         // full: recycle a spark or the oldest cloud
    {
        for(i = 0; i < RC_MAX_OBJ; i++)
        {
            if(rc_obj[i].kind != OB_SPARK && rc_obj[i].kind != OB_CLOUD) continue;
            if(pick == 0xFFFFu || rc_obj[i].kind == OB_SPARK ||
               rc_obj[i].age > oldest)
            {
                pick   = i;
                oldest = rc_obj[i].age;
                if(rc_obj[i].kind == OB_SPARK) break;
            }
        }
        if(pick == 0xFFFFu) return NULL;
    }

    o = &rc_obj[pick];
    o->x = o->y = o->vx = o->vy = o->z = 0;
    o->kind = kind;
    o->pal  = 0;
    o->sc   = 0;
    o->life = 0;
    o->age  = 0;
    o->aux  = 0;
    o->alive = 1;
    return o;
}


static void DropMana(int16_t x, int16_t y)
{
    Obj *o = NewObj(OB_MANA);

    if(o == NULL) return;                       // object list full: no bottle this time
    o->x    = x;
    o->y    = y;
    o->z    = 0;
    o->pal  = PT_FLASK_MANA;
    o->life = MANA_BOTTLE_LIFE;
}


static void AddSpark(int16_t x, int16_t y, int16_t z, uint16_t sc, uint16_t pal, uint16_t life)
{
    Obj *o = NewObj(OB_SPARK);

    if(o == NULL) return;
    o->x = x;  o->y = y;  o->z = z;
    o->sc = sc;  o->pal = pal;  o->life = life;
}


// A flask breaks: splash everything near, leave a puff (venom: a lingering cloud).
static void Shatter(Obj *o)
{
    uint16_t kind = o->aux;
    int16_t  rad  = rc_kPotRadius[kind];
    uint16_t dmg  = ScaledDmg(rc_kPotDmg[kind]);
    uint16_t i;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        Enemy *e = &rc_en[i];

        if(!e->alive) continue;
        if(Dist10(e->x - o->x, e->y - o->y) >= rad + (rc_kEnemy[e->type].radius >> 1))
            continue;

        rc_DamageEnemyEx(e, dmg, 0, 0, true);
        if(!e->alive) continue;

        if(kind == PK_FIRE)       e->burn = 90;
        else if(kind == PK_FROST) { e->freeze = 40; e->slow = 220; }
        else                      e->slow = 60;
    }

    o->kind = OB_CLOUD;                         // the flask becomes its own splash cloud
    o->age  = 0;
    o->life = rc_kPotLife[kind];
    o->sc   = rc_kPotScale[kind];
    o->pal  = PT_PUFF_FIRE + kind;
    o->z    = 0;
    o->vx   = o->vy = 0;
    rc_Sfx(&sfx_explosion);
}


void rc_UpdateObjects(void)
{
    uint16_t i, j;
    int16_t  nx, ny;

    for(i = 0; i < RC_MAX_OBJ; i++)
    {
        Obj *o = &rc_obj[i];

        if(!o->alive) continue;

        switch(o->kind)
        {
            case OB_FLASK:
                o->age++;
                nx = o->x + o->vx;
                ny = o->y + o->vy;
                if(Blocked(nx, ny, 60)) { Shatter(o); break; }
                o->x = nx;
                o->y = ny;
                o->z = (int16_t)(9 - (int16_t)((o->age * 7u) / o->life));
                for(j = 0; j < RC_MAX_ENEMIES; j++)
                {
                    if(!rc_en[j].alive) continue;
                    if(Dist10(rc_en[j].x - o->x, rc_en[j].y - o->y) <
                       rc_kEnemy[rc_en[j].type].radius + 150)
                    {
                        Shatter(o);
                        break;
                    }
                }
                if(o->kind == OB_FLASK && o->age >= o->life) Shatter(o);
                break;

            case OB_BOLT:                       // enemy laser or dragon flame: dodge it
                nx = o->x + o->vx;
                ny = o->y + o->vy;
                if(Blocked(nx, ny, 80)) { o->alive = 0; break; }
                o->x = nx;
                o->y = ny;
                if(Dist10(rc_px - o->x, rc_py - o->y) < (o->aux ? 360 : 300))
                {
                    o->alive = 0;
                    rc_HurtPlayer();               // (does nothing during invulnerability / Aegis)
                    break;
                }
                if(++o->age >= o->life) o->alive = 0;
                break;

            case OB_CLOUD:
                if(++o->age >= o->life) { o->alive = 0; break; }
                if(o->aux == PK_VENOM && (o->age % 12u) == 0)
                {
                    for(j = 0; j < RC_MAX_ENEMIES; j++)
                    {
                        Enemy *e = &rc_en[j];

                        if(!e->alive) continue;
                        if(Dist10(e->x - o->x, e->y - o->y) >=
                           rc_kPotRadius[PK_VENOM] + (rc_kEnemy[e->type].radius >> 1))
                            continue;
                        rc_DamageEnemyEx(e, (uint16_t)(1u + rc_lvDmg / 3u), 0, 0, true);
                        if(e->alive) e->slow = 30;
                    }
                }
                break;

            case OB_MANA:                       // mana bottle on the floor
                if(++o->age >= o->life) { o->alive = 0; break; }
                o->z = (int16_t)((o->age >> 3) & 1u);                   // little bob
                if(rc_mana < MANA_MAX &&
                   Dist10(rc_px - o->x, rc_py - o->y) < MANA_PICKUP_R)
                {
                    rc_mana += MANA_BOTTLE;
                    if(rc_mana > MANA_MAX) rc_mana = MANA_MAX;
                    o->alive = 0;
                    rc_Sfx(&sfx_powerup);
                }
                break;

            default:                            // OB_SPARK
                if(++o->age >= o->life) o->alive = 0;
                break;
        }
    }
}


//-----------------------------------------------------------------------------
// Staffs: hitscan beams
//-----------------------------------------------------------------------------
static void FireBeam(int16_t angle, uint16_t st)
{
    uint16_t tile, side;
    int16_t  c, s, best;
    int32_t  wall, bestAlong, along, perp;
    uint16_t hitMask = 0, left, i, dmg;
    int16_t  rx, ry;

    angle &= RC_ANGLE_MASK;
    wall = (int32_t)rc_RC_CastRay(angle, &tile, &side) << 2;       // Q8 -> Q10
    c = COS(angle);
    s = SIN(angle);

    left = 1u + rc_kStaff[st].pierce + ((rc_traits & (1u << TR_PIERCE)) ? 1u : 0u);

    while(left--)
    {
        best      = -1;
        bestAlong = wall;

        for(i = 0; i < RC_MAX_ENEMIES; i++)
        {
            if(!rc_en[i].alive || (hitMask & (1u << i))) continue;

            rx    = rc_en[i].x - rc_px;
            ry    = rc_en[i].y - rc_py;
            along = ((int32_t)rx * c + (int32_t)ry * s) >> 14;
            if(along <= 0 || along >= bestAlong) continue;

            perp = ((int32_t)ry * c - (int32_t)rx * s) >> 14;
            if(perp < 0) perp = -perp;
            if(perp > rc_kEnemy[rc_en[i].type].radius) continue;

            best      = (int16_t)i;
            bestAlong = along;
        }

        if(best < 0) break;

        hitMask |= (1u << best);

        dmg = ScaledDmg(rc_kStaff[st].dmg);
        if((rc_traits & (1u << TR_LUCKY)) && (Rand16() % 5u) == 0) dmg *= 2u;

        DamageEnemy(&rc_en[best], dmg, c, s);
    }
}


static void Fire(void)
{
    uint16_t     st = rc_equip;
    const Staff *sp = &rc_kStaff[st];
    uint16_t     i;
    int16_t      off;

    rc_cdMax[st] = StaffCooldown(st);
    rc_cd[st]    = rc_cdMax[st];
    rc_fxN       = sp->beams;
    rc_fxColor   = sp->color;

    for(i = 0; i < sp->beams; i++)
    {
        off = (int16_t)((((int16_t)(2 * i) - (int16_t)(sp->beams - 1)) * (int16_t)sp->spread) / 2);
        FireBeam(rc_ang + off, st);
        rc_fxX[i] = (int16_t)(RC_VIEW_X0 + RC_VIEW_W / 2 + off * RC_PX_PER_UNIT);
    }

    rc_fxTimer   = 4;
    rc_viewDirty = 2;
    if(rc_sfxHold == 0) Buzzer_PlaySfx(rc_kStaffSfx[st]);
    rc_stepBlock = 5;                            // footsteps never cut a shot off
}


//-----------------------------------------------------------------------------
// Magic items
//-----------------------------------------------------------------------------
static bool ThrowFlask(uint16_t kind)
{
    int16_t c = COS(rc_ang);
    int16_t s = SIN(rc_ang);
    int16_t sx, sy;
    Obj    *o = NewObj(OB_FLASK);

    if(o == NULL) return false;

    sx = rc_px + (int16_t)(((int32_t)c * 300L) >> 14);
    sy = rc_py + (int16_t)(((int32_t)s * 300L) >> 14);
    if(Blocked(sx, sy, 60)) { sx = rc_px; sy = rc_py; }       // nose against a wall

    o->x    = sx;
    o->y    = sy;
    o->vx   = (int16_t)(((int32_t)c * 110L) >> 14);
    o->vy   = (int16_t)(((int32_t)s * 110L) >> 14);
    o->z    = 9;
    o->aux  = kind;
    o->life = 42;
    o->pal  = PT_FLASK_FIRE + kind;
    Buzzer_PlaySfx(&sfx_jump);
    return true;
}


// Nearest visible enemies in front of the player (arc +-90 units, line of sight).
static uint16_t AcquireTargets(uint16_t maxN, uint16_t *out)
{
    int16_t  c = COS(rc_ang);
    int16_t  s = SIN(rc_ang);
    uint16_t cand[RC_MAX_ENEMIES], candD[RC_MAX_ENEMIES];
    uint16_t nc = 0, n = 0, i, k, tile, side;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        const Enemy *e = &rc_en[i];
        int16_t rx, ry, along, sd, ratio, theta;
        uint16_t wd;

        if(!e->alive) continue;
        rx    = e->x - rc_px;
        ry    = e->y - rc_py;
        along = (int16_t)(((int32_t)rx * c + (int32_t)ry * s) >> 14);
        if(along < 200) continue;

        sd    = (int16_t)(((int32_t)ry * c - (int32_t)rx * s) >> 14);
        ratio = (int16_t)(((int32_t)sd * 256L) / along);
        theta = (ratio < 0) ? -ratio : ratio;
        if(theta > 256) continue;
        theta = rc_atan[theta];
        if(theta > 90) continue;
        if(ratio < 0) theta = -theta;

        wd = rc_RC_CastRay(rc_ang + theta, &tile, &side);           // Q8
        if(wd < (uint16_t)(along >> 2)) continue;               // a wall is in the way

        cand[nc]  = i;
        candD[nc] = (uint16_t)along;
        nc++;
    }

    while(n < maxN && nc > 0)
    {
        k = 0;
        for(i = 1; i < nc; i++)
            if(candD[i] < candD[k]) k = i;
        out[n++] = cand[k];
        nc--;
        cand[k]  = cand[nc];
        candD[k] = candD[nc];
    }
    return n;
}


static bool CastTome(void)
{
    uint16_t idx[3], n, i;
    uint16_t dmg = ScaledDmg(3);

    n = AcquireTargets(3, idx);
    if(n == 0) { rc_Sfx(&sfx_menu_bump); return false; }

    for(i = 0; i < n; i++)
    {
        Enemy *e = &rc_en[idx[i]];

        AddSpark(e->x, e->y, 6, 8, PT_PUFF_ARCANE, 8);
        DamageEnemy(e, dmg, 0, 0);
    }
    Buzzer_PlaySfx(&sfx_staff_prism);
    return true;
}


static void CastWarp(void)
{
    int16_t c = COS(rc_ang);
    int16_t s = SIN(rc_ang);
    int16_t nx, ny, i;

    for(i = 0; i < 24; i++)                     // up to 24 * 128 = 3 tiles
    {
        nx = rc_px + (int16_t)(((int32_t)c * 128L) >> 14);
        ny = rc_py + (int16_t)(((int32_t)s * 128L) >> 14);
        if(Blocked(nx, ny, RC_PLAYER_R)) break;
        rc_px = nx;
        rc_py = ny;
    }

    if(rc_invuln < 20) rc_invuln = 20;
    rc_stepAcc   = 0;
    rc_viewDirty = 2;
    Buzzer_PlaySfx(&sfx_staff_storm);
}


static void CastAegis(void)
{
    uint16_t i;

    rc_aegis = 150;
    rc_hud  |= HUD_HINT;

    for(i = 0; i < RC_MAX_ENEMIES; i++)         // shockwave
    {
        Enemy  *e = &rc_en[i];
        int16_t dx, dy, d, nx, ny;

        if(!e->alive) continue;
        dx = e->x - rc_px;
        dy = e->y - rc_py;
        d  = Dist10(dx, dy);
        if(d >= 2000 || d <= 0) continue;

        nx = e->x + (int16_t)(((int32_t)dx * 600L) / d);
        ny = e->y + (int16_t)(((int32_t)dy * 600L) / d);
        if(!Blocked(nx, e->y, 230)) e->x = nx;
        if(!Blocked(e->x, ny, 230)) e->y = ny;
        e->slow = 60;
    }
    rc_Sfx(&sfx_menu_select);
}


// Returns true if the item was used (so its cooldown starts).
static bool UseItem(uint16_t it)
{
    switch(it)
    {
        case IT_FIRE:
        case IT_FROST:
        case IT_VENOM:
            return ThrowFlask(it);                      // IT_ order == PK_ order

        case IT_ELIXIR:
            if(rc_hp >= rc_maxHp) { rc_Sfx(&sfx_menu_bump); return false; }
            rc_hp += 2;
            if(rc_hp > rc_maxHp) rc_hp = rc_maxHp;
            rc_hud |= HUD_HEARTS;
            rc_Sfx(&sfx_powerup);
            return true;

        case IT_HASTE:
            rc_haste = 300;
            rc_hud  |= HUD_HINT;
            rc_Sfx(&sfx_powerup);
            return true;

        case IT_TOME:
            return CastTome();

        case IT_WARP:
            CastWarp();
            return true;

        default:                                        // IT_AEGIS
            CastAegis();
            return true;
    }
}


void rc_UseEquipped(void)
{
    uint16_t slot = rc_equip;
    uint16_t it;
    uint16_t cost = rc_SlotMana(slot);

    if(rc_cd[slot]) return;

    if(rc_mana < cost)                                   // not enough mana
    {
        rc_cdMax[slot] = 10;
        rc_cd[slot]    = 10;                             // retry delay (holding U won't spam)
        rc_manaFlash   = 12;
        rc_Sfx(&sfx_menu_bump);
        return;
    }

    if(slot < NUM_STAFF)
    {
        Fire();
        rc_mana -= cost;
        return;
    }

    it = slot - NUM_STAFF;
    if(UseItem(it))
    {
        rc_mana       -= cost;                           // only paid if the item was used
        rc_cdMax[slot] = rc_kItem[it].cooldown;
        rc_cd[slot]    = rc_kItem[it].cooldown;
    }
    else
        rc_cd[slot] = 10;                                // brief retry delay
    rc_viewDirty = 2;
}


//-----------------------------------------------------------------------------
// Spawning
//-----------------------------------------------------------------------------
static Enemy *SpawnEnemy(uint16_t type, int16_t x, int16_t y)
{
    uint16_t i;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        if(!rc_en[i].alive)
        {
            int16_t hp = rc_kEnemy[type].hp;

            if(type == ET_LICH)                         // each Lich is tougher than the last
                hp = (int16_t)(hp + 50 * (int16_t)((rc_level + 1u) / RC_BOSS_EVERY - 1u));
            else if(type == ET_DRAGON)
                hp = (int16_t)(hp + 100 * (int16_t)((rc_level + 1u) / (RC_BOSS_EVERY * 2u) - 1u));
            else                                        // later rounds are tougher
                hp = (int16_t)(((int32_t)hp * (8 + rc_level)) / 8);

            rc_en[i].x = x;      rc_en[i].y = y;
            rc_en[i].hp = hp;    rc_en[i].type = type;
            rc_en[i].flash = 0;  rc_en[i].slow = 0;
            rc_en[i].freeze = 0; rc_en[i].burn = 0;
            rc_en[i].aux = 0;    rc_en[i].aux2 = 0;
            rc_en[i].alive = 1;
            rc_alive++;
            rc_hud |= HUD_LEFT;
            return &rc_en[i];
        }
    }
    return NULL;
}


static uint16_t CountType(uint16_t type)
{
    uint16_t i, n = 0;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
        if(rc_en[i].alive && rc_en[i].type == type) n++;
    return n;
}


void rc_TrySpawn(void)
{
    uint16_t tries, idx = 0, type, r, gap;
    uint16_t behCap;
    bool     found = false;

    if(rc_spawnTimer) { rc_spawnTimer--; return; }
    if(!rc_toSpawn || rc_alive >= rc_lv.maxAlive || rc_spCount == 0) return;

    // First marker in an UNLOCKED section that is not right on top of the player.
    for(tries = 0; tries < rc_spCount; tries++)
    {
        idx = rc_spawnIdx;
        rc_spawnIdx = (rc_spawnIdx + 1u) % rc_spCount;
        if(!rc_secOpen[rc_spSec[idx]]) continue;
        if(rc_lv.boss && (rc_level + 1u) >= (RC_BOSS_EVERY * 2u) && rc_spSec[idx] != 6u) continue;
        if(Dist10(rc_spX[idx] - rc_px, rc_spY[idx] - rc_py) > SPAWN_MIN_DIST)
        {
            found = true;
            break;
        }
    }
    if(!found) { rc_spawnTimer = 20; return; }

    gap = rc_lv.gap;

    if(rc_lv.boss)
    {
        type = ((rc_level + 1u) >= (RC_BOSS_EVERY * 2u)) ? ET_DRAGON : ET_LICH;
        rc_bossSpawned = 1;
        rc_bossAlive   = 1;
        rc_toSpawn     = 1;                              // (decremented below -> 0)
    }
    else
    {
        behCap = 1u + rc_level / 6u;
        if(behCap > 3u) behCap = 3u;

        r    = Rand16() % 100u;
        type = ET_GOBLIN;
        if(r < rc_lv.pBeh)
        {
            if(CountType(ET_BEHOLDER) < behCap) type = ET_BEHOLDER;
        }
        else if(r < rc_lv.pBeh + rc_lv.pBrute)                         type = ET_HOBGOB;
        else if(r < rc_lv.pBeh + rc_lv.pBrute + rc_lv.pBat)             type = ET_BAT;
        else if(r < rc_lv.pBeh + rc_lv.pBrute + rc_lv.pBat + rc_lv.pSkel) type = ET_SKELETON;
    }

    SpawnEnemy(type, rc_spX[idx], rc_spY[idx]);
    rc_toSpawn--;
    rc_spawnTimer = gap;
}


//-----------------------------------------------------------------------------
// Enemy behaviour
//-----------------------------------------------------------------------------
uint16_t rc_BeholderCadence(void)
{
    uint16_t cut = (uint16_t)(2u * rc_level);

    if(cut > 45u) cut = 45u;
    return (uint16_t)(100u - cut);                      // frames between shots
}


// Beholders aim at where you ARE: strafe and the red lasers miss.
void rc_BeholderShoot(const Enemy *e)
{
    int16_t dx   = rc_px - e->x;
    int16_t dy   = rc_py - e->y;
    int16_t dist = Dist10(dx, dy);
    int16_t vx, vy, k, kmax;

    if(dist < 400) return;

    vx = (int16_t)(((int32_t)dx * RC_BOLT_SPEED) / dist);
    vy = (int16_t)(((int32_t)dy * RC_BOLT_SPEED) / dist);
    kmax = (rc_level >= 8) ? 1 : 0;                      // deeper: three-way fan

    for(k = -kmax; k <= kmax; k++)
    {
        Obj *o = NewObj(OB_BOLT);

        if(o == NULL) break;
        o->x    = e->x;
        o->y    = e->y;
        o->vx   = (int16_t)(vx - (int16_t)(((int32_t)vy * k * 56L) >> 8));
        o->vy   = (int16_t)(vy + (int16_t)(((int32_t)vx * k * 56L) >> 8));
        o->z    = 6;
        o->life = 130;
        o->pal  = PT_BOLT;
    }
    rc_SfxSoft(&sfx_laser);
}


void rc_DragonBreath(const Enemy *e)
{
    int16_t dx = rc_px - e->x;
    int16_t dy = rc_py - e->y;
    int16_t dist = Dist10(dx, dy);
    int16_t vx, vy, k;

    if(dist < 400) return;
    vx = (int16_t)(((int32_t)dx * 68L) / dist);
    vy = (int16_t)(((int32_t)dy * 68L) / dist);
    for(k = -1; k <= 1; k++)
    {
        Obj *o = NewObj(OB_BOLT);
        if(o == NULL) break;
        o->x = e->x; o->y = e->y;
        o->vx = (int16_t)(vx - (int16_t)(((int32_t)vy * k * 52L) >> 8));
        o->vy = (int16_t)(vy + (int16_t)(((int32_t)vx * k * 52L) >> 8));
        o->z = 4; o->life = 115; o->pal = PT_PUFF_FIRE; o->aux = 1;
    }
    rc_SfxSoft(&sfx_laser);
}


void rc_LichSummon(const Enemy *lich, uint16_t n)
{
    uint16_t k;

    for(k = 0; k < n; k++)
    {
        int16_t sx = lich->x + ((k == 0) ? 520 : (k == 1) ? -520 : 0);
        int16_t sy = lich->y + ((k == 2) ? 520 : 0);
        Enemy  *p;

        if(rc_alive >= RC_MAX_ENEMIES - 1) break;
        if(Blocked(sx, sy, 230)) { sx = lich->x; sy = lich->y; }

        p = SpawnEnemy(ET_SKELETON, sx, sy);
        if(p == NULL) break;
        p->aux = 1;                                     // marks "summoned"
        AddSpark(sx, sy, 6, 10, PT_PUFF_ARCANE, 10);
    }
    rc_SfxSoft(&sfx_powerup);
}


//-----------------------------------------------------------------------------
// Path-finding: a breadth-first "steps to the player" map over the 16 x 16 grid.
// Rebuilt whenever the player changes tile or a door opens (a few hundred cells).
// Enemies that can see you walk straight at you; otherwise they follow the map.
//-----------------------------------------------------------------------------
const int16_t rc_kNbDx[4] = { 1, -1, 0, 0 };

const int16_t rc_kNbDy[4] = { 0, 0, 1, -1 };
